import{_ as i,o as e,c as o,aw as a}from"./chunks/framework.DLufY-ao.js";const r="/workbook/assets/git1.BQd1CHIO.jpg",l="/workbook/assets/git2.tpmDoaZP.jpg",u=JSON.parse('{"title":"Принцип работы","description":"","frontmatter":{},"headers":[],"relativePath":"common/git/theory/principle.md","filePath":"wiki/dev-commit/common/git/theory/principle.md"}'),s={name:"common/git/theory/principle.md"};function n(c,t,d,m,g,h){return e(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="принцип-работы" tabindex="-1">Принцип работы <a class="header-anchor" href="#принцип-работы" aria-label="Permalink to &quot;Принцип работы&quot;">​</a></h1><h2 id="указатели" tabindex="-1">Указатели <a class="header-anchor" href="#указатели" aria-label="Permalink to &quot;Указатели&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Определение</p><ul><li><strong>HEAD</strong> - ссылка на последний коммит и на текущую ветку</li><li><strong>Branch</strong> - ветка-указатель на коммит. На один коммит может быть несколько веток-указателей (н-р, сразу после создания новой ветки)</li><li><strong>remotes/origin/master</strong> - указатель, показывающий, на каком коммите находится указатель ветки в удаленном репозитории. Ветки слежения удаленного репозитория</li></ul></div><ul><li>Локально <em>origin</em> нет</li></ul><h2 id="статусы" tabindex="-1">Статусы <a class="header-anchor" href="#статусы" aria-label="Permalink to &quot;Статусы&quot;">​</a></h2><ol><li><strong>Untracked</strong> - после добавления нового файла</li><li><strong>Staged</strong> - после <em>git add</em></li><li><strong>Modified</strong> - после изменения существующего файла</li><li><strong>Committed</strong> - после <em>git commit</em></li></ol><h2 id="правила" tabindex="-1">Правила <a class="header-anchor" href="#правила" aria-label="Permalink to &quot;Правила&quot;">​</a></h2><ul><li>Каждый коммит ссылается на предыдущий. В качестве ссылки выступает хэш-сумма коммита</li></ul><h2 id="local-operation" tabindex="-1">Local Operation <a class="header-anchor" href="#local-operation" aria-label="Permalink to &quot;Local Operation&quot;">​</a></h2><img src="'+r+'" style="width:450px;"><ul><li><strong>I. Working Directory</strong> - рабочий каталог</li><li><strong>II. Staging Area</strong> - область подготовленных файлов</li><li><strong>III. Git Directory (Repository)</strong> - каталог git</li></ul><p><strong>Этапы</strong></p><ol><li>Внесение изменений в файлы рабочего каталога</li><li>Подготовка файлов: добавление их слепков в область Staging Area</li><li><code>commit</code> - берет подготовленные файлы из индекса Staging Area и помещает их в Git Directory на постоянное хранение</li></ol><h2 id="file-status-lifecycle" tabindex="-1">File Status Lifecycle <a class="header-anchor" href="#file-status-lifecycle" aria-label="Permalink to &quot;File Status Lifecycle&quot;">​</a></h2><img src="'+l+'" style="width:450px;"><ul><li>Файл в Working Directory может находиться под версионным контролем (<em>unmodified, modified, staged</em>) или быть неотслеживаемым (<em>untracked</em>)</li></ul>',16)])])}const _=i(s,[["render",n]]);export{u as __pageData,_ as default};
